import { View, Text, Pressable, Modal, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [open, setOpen] = useState(false);
  return (
    <View style={styles.s}>
      <Pressable nativeID="open" style={styles.b} onPress={() => setOpen(true)}><Text style={styles.t}>Хурдан үзэх</Text></Pressable>
      {/* энд бичнэ үү: Modal — visible={open}, дотор нь Хаах товч */}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, alignItems: "center", justifyContent: "center" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
  sheet: { margin: 40, backgroundColor: "#fff", padding: 24, borderRadius: 16, gap: 12 },
  x: { backgroundColor: "#e2e8f0", padding: 10, borderRadius: 8, alignItems: "center" },
});

registerRootComponent(App);

import { View, Text, Pressable, Modal, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [open, setOpen] = useState(false);
  return (
    <View style={styles.s}>
      <Pressable nativeID="open" style={styles.b} onPress={() => setOpen(true)}><Text style={styles.t}>Хурдан үзэх</Text></Pressable>
      <Modal visible={open} transparent onRequestClose={() => setOpen(false)}>
        <View style={styles.sheet}>
          <Text nativeID="title" style={{ fontSize: 18, fontWeight: "bold" }}>Нарны шил — 89,000₮</Text>
          <Pressable nativeID="close" style={styles.x} onPress={() => setOpen(false)}><Text>Хаах</Text></Pressable>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, alignItems: "center", justifyContent: "center" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
  sheet: { margin: 40, backgroundColor: "#fff", padding: 24, borderRadius: 16, gap: 12 },
  x: { backgroundColor: "#e2e8f0", padding: 10, borderRadius: 8, alignItems: "center" },
});

registerRootComponent(App);
